404c5a2 Fix completion filtering for numeric task state
 index.html | 3 ++-
 1 file changed, 2 insertions(+), 1 deletion(-)
commit 404c5a293b2090472e59e01dbf074b285744a4ad
Author: Experiment Builder <builder@experiment.invalid>
Date:   Sat Oct 10 18:54:13 2026 +0000

    Fix completion filtering for numeric task state

diff --git a/index.html b/index.html
index 0fbe078..00bd396 100644
--- a/index.html
+++ b/index.html
@@ -114,7 +114,8 @@
         const filter = app.querySelector('#task-filter');
         const priorityFilter = app.querySelector('#priority-filter');
         const applyFilters = () => app.querySelectorAll('.task-row').forEach(row => {
-          const completionMatches = filter.value === 'All' || (filter.value === 'Open' ? row.dataset.completed !== 'true' : row.dataset.completed === 'true');
+          const completed = row.dataset.completed === 'true' || row.dataset.completed === '1';
+          const completionMatches = filter.value === 'All' || (filter.value === 'Open' ? !completed : completed);
           const date = row.dataset.dueDate;
           const dateMatches = !appliedRange[0] && !appliedRange[1] ? true : Boolean(date) && (!appliedRange[0] || date >= appliedRange[0]) && (!appliedRange[1] || date <= appliedRange[1]);
           const title = row.querySelector('span').textContent;
